export type BackupConfiguration = {
	/**
	 * @description The interval in hours between each backup.
	 * @type number | undefined
	 */
	backupPeriodInHours?: number | undefined;
	/**
	 * @description The minimum duration in hours for which the backups are available. Must be a whole number of days between 24 (1 day) and 1080 (45 days) — i.e. a multiple of 24.
	 * @type number | undefined
	 */
	backupRetentionPeriodInHours?: number | undefined;
	/**
	 * @description The time in HH:MM format for the backups to be performed (evaluated in UTC timezone). When defined the backup period resets to every 24 hours.
	 * @type string | undefined
	 */
	backupStartTime?: string | undefined;
};

export const backupStatusEnum = {
	done: "done",
	error: "error",
	in_progress: "in_progress",
} as const;

export type BackupStatusEnumKey = (typeof backupStatusEnum)[keyof typeof backupStatusEnum];

export const backupTypeEnum = {
	full: "full",
	incremental: "incremental",
} as const;

export type BackupTypeEnumKey = (typeof backupTypeEnum)[keyof typeof backupTypeEnum];

export type Backup = {
	/**
	 * @description Unique backup ID.
	 *
	 * Format: `uuid`
	 * @type string | undefined
	 */
	id?: string | undefined;
	/**
	 * @description Status of the backup: \'done\', \'error\', \'in_progress\'.
	 * @type string | undefined
	 */
	status?: BackupStatusEnumKey | undefined;
	/**
	 * @description Name
	 * @type string | undefined
	 */
	serviceId?: string | undefined;
	/**
	 * @description Backup start timestamp. ISO-8601.
	 *
	 * Format: `date-time`
	 * @type string | undefined
	 */
	startedAt?: string | undefined;
	/**
	 * @description Backup finish timestamp. ISO-8601. Available only for finished backups
	 *
	 * Format: `date-time`
	 * @type string | undefined
	 */
	finishedAt?: string | undefined;
	/**
	 * @description Size of the backup in bytes.
	 * @type number | undefined
	 */
	sizeInBytes?: number | undefined;
	/**
	 * @description Time in seconds it took to perform the backup. If the status still in_progress, this is the time in seconds since the backup started until now.
	 * @type number | undefined
	 */
	durationInSeconds?: number | undefined;
	/**
	 * @description Backup type (\"full\" or \"incremental\").
	 * @type string | undefined
	 */
	type?: BackupTypeEnumKey | undefined;
	/**
	 * @description Backup name on the external backup bucket.
	 * @type string | undefined
	 */
	backupName?: string | undefined;
	/**
	 * @description Backup bucket where the backup is stored.
	 */
	bucket?:
		| (AwsBackupBucketProperties | GcpBackupBucketProperties | AzureBackupBucketProperties)
		| undefined;
};

export const snapshotStatusEnum = {
	done: "done",
	error: "error",
	in_progress: "in_progress",
	throttled: "throttled",
} as const;

export type SnapshotStatusEnumKey = (typeof snapshotStatusEnum)[keyof typeof snapshotStatusEnum];

export type Snapshot = {
	/**
	 * @description Unique snapshot ID.
	 *
	 * Format: `uuid`
	 * @type string | undefined
	 */
	id?: string | undefined;
	/**
	 * @description Status of the snapshot: \'done\', \'error\', \'in_progress\', \'throttled\'. \'throttled\' means snapshot creation was rate-limited and will be retried.
	 * @type string | undefined
	 */
	status?: SnapshotStatusEnumKey | undefined;
	/**
	 * @description ID of the service the snapshot was created from.
	 * @type string | undefined
	 */
	serviceId?: string | undefined;
	/**
	 * @description Snapshot start timestamp. ISO-8601.
	 *
	 * Format: `date-time`
	 * @type string | undefined
	 */
	startedAt?: string | undefined;
	/**
	 * @description Snapshot finish timestamp. ISO-8601. Available only for finished snapshots
	 *
	 * Format: `date-time`
	 * @type string | undefined
	 */
	finishedAt?: string | undefined;
	/**
	 * @description Size of the snapshot in bytes.
	 * @type number | undefined
	 */
	sizeInBytes?: number | undefined;
	/**
	 * @description Time in seconds it took to perform the snapshot. If the status is in_progress or throttled, this is the time in seconds since the snapshot started until now.
	 * @type number | undefined
	 */
	durationInSeconds?: number | undefined;
	/**
	 * @description Snapshot type. Always \"full\" — snapshots never chain off a parent.
	 * @type string | undefined
	 */
	type?: "full" | undefined;
	/**
	 * @description Snapshot name on the external backup bucket.
	 * @type string | undefined
	 */
	backupName?: string | undefined;
	/**
	 * @description Backup bucket where the snapshot is stored.
	 */
	bucket?:
		| (AwsBackupBucketProperties | GcpBackupBucketProperties | AzureBackupBucketProperties)
		| undefined;
};

export type SnapshotConfiguration = {
	/**
	 * @description Whether scheduled snapshots are enabled for the service.
	 * @type boolean | undefined
	 */
	enabled?: boolean | undefined;
	/**
	 * @description Interval between snapshots, in minutes. Set together with timeFrame; only supported preset pairs are accepted.
	 * @type number | undefined
	 */
	gap?: number | undefined;
	/**
	 * @description Retention window the snapshots cover, in minutes. Set together with gap; only supported preset pairs are accepted.
	 * @type number | undefined
	 */
	timeFrame?: number | undefined;
};

